function validate([l1, l2]) {
  for (const [name, list] of [['l1', l1], ['l2', l2]]) {
    if (list.length < 1 || list.length > 100) return `${name} needs 1 to 100 digits.`;
    if (list.some(d => d < 0 || d > 9)) return `Every node of ${name} holds a digit from 0 to 9.`;
    if (list.length > 1 && list[0] === 0) return `${name} must not start with 0 unless it is just [0].`;
  }
  return null;
}

