    let prev = null;
    while (head !== null) {
      const next = head.next;
      head.next = prev;
      prev = head;
      head = next;
    }
    return prev;
  }

  let a = reverse(l1);
  let b = reverse(l2);
  let carry = 0;
  let result = null;
  while (a !== null || b !== null || carry > 0) {
    let sum = carry;
    if (a !== null) {
      sum += a.val;
      a = a.next;
    }
    if (b !== null) {
      sum += b.val;
      b = b.next;
    }
    carry = Math.floor(sum / 10);
    result = new ListNode(sum % 10, result);
  }
  return result;
}

