function addTwoNumbers(l1, l2) {
  // Copy the digits into arrays, add them column by column from the right like on paper,
  // then link the digit array into a fresh list.
  const toArray = head => {
    const out = [];
    for (let node = head; node; node = node.next) out.push(node.val);
    return out;
  };
  const x = toArray(l1), y = toArray(l2);
  const sum = [];
  let i = x.length - 1, j = y.length - 1, carry = 0;
  while (i >= 0 || j >= 0 || carry) {
    const total = (i >= 0 ? x[i--] : 0) + (j >= 0 ? y[j--] : 0) + carry;
    sum.unshift(total % 10);
    carry = total >= 10 ? 1 : 0;
  }
  let head = null;
  for (let k = sum.length - 1; k >= 0; k--) head = new ListNode(sum[k], head);
  return head;
}

