function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const number = length => {
    if (length === 1) return [pick(10)];
    // Lean on 9s now and then so long carry chains appear.
    const nines = rand() < 0.3;
    return Array.from({ length }, (_, i) => (i === 0 ? 1 + pick(9) : nines && rand() < 0.8 ? 9 : pick(10)));
  };
  if (size === 'large') return [number(90 + pick(11)), number(90 + pick(11))];
  return [number(1 + pick(6)), number(1 + pick(6))];
}
